#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> bfs(int start, const vector<vector<int>>& graph, vector<int>* parent = nullptr) {
    int n = graph.size();
    vector<int> dist(n, -1);
    if (parent) parent->assign(n, -1);

    queue<int> q;
    q.push(start);
    dist[start] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : graph[u]) {
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            if (parent) (*parent)[v] = u;
            q.push(v);
        }
    }

    int farthest = start;
    for (int i = 0; i < n; ++i)
        if (dist[i] > dist[farthest]) farthest = i;

    return {farthest, move(dist)};
}

long long countAtDistance(int start, int blocked, int target,
                          const vector<vector<int>>& graph) {
    long long count = 0;
    vector<tuple<int, int, int>> st;
    st.emplace_back(start, blocked, 0);

    while (!st.empty()) {
        auto [u, parent, depth] = st.back();
        st.pop_back();

        if (depth == target) {
            ++count;
            continue;
        }
        for (int v : graph[u])
            if (v != parent)
                st.emplace_back(v, u, depth + 1);
    }

    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    int a = bfs(0, graph).first;
    vector<int> parent;
    auto [b, dist] = bfs(a, graph, &parent);

    int diameter = dist[b];
    vector<int> path;
    for (int v = b; v != -1; v = parent[v]) path.push_back(v);
    reverse(path.begin(), path.end());

    long long ways = 0;
    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        int radius = diameter / 2;
        long long sum = 0, sumSquares = 0;

        for (int neighbor : graph[center]) {
            long long count = countAtDistance(neighbor, center, radius - 1, graph);
            sum += count;
            sumSquares += count * count;
        }

        ways = (sum * sum - sumSquares) / 2;
    } else {
        int leftCenter = path[diameter / 2];
        int rightCenter = path[diameter / 2 + 1];
        int radius = (diameter + 1) / 2;

        long long leftCount = countAtDistance(leftCenter, rightCenter, radius, graph);
        long long rightCount = countAtDistance(rightCenter, leftCenter, radius, graph);
        ways = leftCount * rightCount;
    }

    cout << diameter + 1 << '\n' << ways << '\n';
    return 0;
}
